"""Brute-force solvers for Independent Set and Clique, from the definitions."""

from __future__ import annotations

from itertools import combinations


def _has_independent_set(n, edges, k):
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = {frozenset((u, v)) for u, v in edges}
    for size in range(k, n + 1):
        for subset in combinations(range(n), size):
            if all(frozenset((a, b)) not in edge_set
                   for a, b in combinations(subset, 2)):
                return True
    return False


def _has_clique(n, edges, k):
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = {frozenset((u, v)) for u, v in edges}
    for size in range(k, n + 1):
        for subset in combinations(range(n), size):
            if all(frozenset((a, b)) in edge_set
                   for a, b in combinations(subset, 2)):
                return True
    return False


def solve_independent_set(instance):
    return _has_independent_set(instance["n"], instance["edges"], instance["k"])


def solve_clique(instance):
    return _has_clique(instance["n"], instance["edges"], instance["k"])
EOF
